import json
from .runtime import ROOT,Run,state,publish,checkpoint,sha

def main():
    st=state();assert st['stages']['G5']=='passed_seen_timing_independent_not_run';run=Run('g6_acceptance','four native/CI PDF versions, claims/source/numeric review',dict(working_draft=True,no_independent_positive_claim=True));print(run.id,flush=True);audit=json.loads((ROOT/'docs/research_v3/PDF_NUMERIC_AUDIT.json').read_text());assert len(audit['papers'])==4
